ALTER TABLE public.landing_pages ADD COLUMN form_config jsonb NOT NULL DEFAULT '{}'::jsonb;
COMMENT ON COLUMN public.landing_pages.form_config IS 'Per-page optional field labels/visibility/requirements and custom questions; name/email always required.';
CREATE OR REPLACE FUNCTION public.claim_community_message(_context text, _reference_id uuid) RETURNS boolean LANGUAGE plpgsql SET search_path TO 'public' AS $function$ DECLARE claimed boolean; BEGIN IF _context NOT IN ('community_plan','community_premium','community_request','community_response','lp_activation','lp_admin_notice','lp_rd_conversion') THEN RETURN false; END IF; INSERT INTO public.community_message_claims(context,reference_id) VALUES(_context,_reference_id) ON CONFLICT(context,reference_id) DO UPDATE SET state='sending',claimed_at=now(),updated_at=now() WHERE community_message_claims.state='failed' OR (community_message_claims.state='sending' AND community_message_claims.claimed_at<now()-interval '10 minutes') RETURNING true INTO claimed; RETURN coalesce(claimed,false); END $function$;
REVOKE ALL ON FUNCTION public.claim_community_message(text,uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.claim_community_message(text,uuid) TO service_role;
INSERT INTO public.system_changelog(version,title,description,category,changes) VALUES('3.58.0','Correções das LPs integradas','Formulários configuráveis, compartilhamento individual, envios recuperáveis e conversão RD Station.','improvement','["Configuração por LP com nome/e-mail obrigatórios", "Avisos de instalação restritos à plataforma", "Metadados individuais no Cloudflare", "Envios de ativação e aviso administrativo auditáveis", "Conversão RD Station no servidor"]'::jsonb);